  var lblCache = {};
  function lblMat(text, bg, fg, aspect, rep) {
    var k = text + bg + fg + aspect.toFixed(2) + rep;
    if (lblCache[k]) return lblCache[k];
    var W2 = 512, H2 = Math.max(32, Math.round(W2 / aspect));
    var c = cv(W2, H2), g = c.getContext('2d');
    g.fillStyle = bg; g.fillRect(0, 0, W2, H2);
    g.fillStyle = 'rgba(255,255,255,0.12)'; g.fillRect(0, 0, W2, H2 * 0.12);
    g.fillStyle = fg; g.textAlign = 'center'; g.textBaseline = 'middle';
    var fs = Math.min(H2 * 0.5, (W2 / rep) * 0.9 / Math.max(2, text.length) * 1.7);
    g.font = '700 ' + fs + 'px "IBM Plex Sans", Arial, sans-serif';
    for (var i = 0; i < rep; i++) g.fillText(text, W2 * (i + 0.5) / rep, H2 / 2);
    var t = new THREE.CanvasTexture(c); t.anisotropy = 4; t.encoding = THREE.sRGBEncoding;
    return (lblCache[k] = new THREE.MeshStandardMaterial({ map: t, roughness: 0.55 }));
  }
