  function itemModel(id, key, L, yaw, useMax, flat) {
    if (!ITEM[id]) return;   // listeden çıkarılmış eşya
    var proc = BUILD[id]; loadModel(key, function () { });
    BUILD[id] = function (g) {
      var e = MC[key];
      if (!e || !e.scene) { proc(g); return; }
      var m = e.scene.clone(true), bb0 = new THREE.Box3().setFromObject(e.scene), s0 = bb0.getSize(new THREE.Vector3());
      var rx = 0, rz = 0;
      if (flat === 'x') rx = Math.PI / 2;   // zorla yatır
      else if (flat !== false) {              // ince/düz eşyaları (kart, harita, tahta) otomatik yatır
        var mx = Math.max(s0.x, s0.y, s0.z);
        if (s0.z < s0.y && s0.z < s0.x && s0.z / mx < 0.16 && s0.y > s0.z * 1.5) rx = Math.PI / 2;
        else if (s0.x < s0.y && s0.x < s0.z && s0.x / mx < 0.16 && s0.y > s0.x * 1.5) rz = Math.PI / 2;
      }
      m.rotation.set(rx, 0, rz);
      var wrap = new THREE.Group(); wrap.add(m); wrap.updateMatrixWorld(true);
      var bb = new THREE.Box3().setFromObject(wrap), sz = bb.getSize(new THREE.Vector3()), ct = bb.getCenter(new THREE.Vector3());
      m.position.set(-ct.x, -bb.min.y, -ct.z);
      var h = new THREE.Group(); h.add(m); h.scale.setScalar(L / (useMax ? Math.max(sz.x, sz.y, sz.z) : Math.max(sz.x, sz.z))); h.rotation.y = yaw || 0; g.add(h);
    };
  }
